fn next(seed:&mut u64)->f64{*seed^=*seed<<13;*seed^=*seed>>7;*seed^=*seed<<17;((*seed>>11) as f64)/(1u64<<53) as f64}
fn rollout(us:&[f64])->f64{let mut x=0.0;let mut cost=0.0;for &u in us{x=0.9*x+u;let uncertainty=0.02*x.abs();cost+=(x-1.0).powi(2)+0.04*u*u+uncertainty;}cost}
fn main(){let(h,pop,elite)=(12,96,10);let(mut mean,mut std)=(vec![0.0;h],vec![0.7;h]);let mut seed=41;for _ in 0..30{let mut batch:Vec<(f64,Vec<f64>)>=(0..pop).map(|_|{let u:Vec<f64>=(0..h).map(|i|(mean[i]+(next(&mut seed)*2.0-1.0)*std[i]).clamp(-1.0,1.0)).collect();(rollout(&u),u)}).collect();batch.sort_by(|a,b|a.0.partial_cmp(&b.0).unwrap());for i in 0..h{mean[i]=batch[..elite].iter().map(|x|x.1[i]).sum::<f64>()/elite as f64;std[i]=(batch[..elite].iter().map(|x|(x.1[i]-mean[i]).powi(2)).sum::<f64>()/elite as f64).sqrt().max(0.04);}}println!("first_action={:.3} predicted_cost={:.4}",mean[0],rollout(&mean));}
